"OLAYLAR_T5_1000B:1250-04-30:0":{"b": ["مصر میں مملوک سلطنت قائم ہوئی — اسکندریہ، المنصورہ اور فیوم مملوکوں کے پاس چلے گئے", "230c1a11"], "d": ["توران شاہ کے بعد شجر الدر اور عز الدین ایبک کے ساتھ مملوک اقتدار قائم ہوا؛ مصر کے شہر (اسکندریہ، المنصورہ، فیوم) مملوک انتظام میں چلے گئے۔ ماخذ ایبک کے تخت نشین ہونے کی تاریخ 3 جولائی 1250 دیتا ہے؛ اٹلس کا دن ایوبی کنیہ کے اختتام (30 اپریل 1250) سے لیا گیا — کنیہ کا دن ماخذ نہیں ہے، فرق بیان کر دیا گیا۔", "f9743bcd"]},
"OLAYLAR_T5_1000B:1250-04-30:1":{"b": ["حلب کے ایوبی الناصر یوسف دمشق کے حاکم بن گئے", "d585985d"], "d": ["مصر میں مملوک اقتدار قائم ہوتے وقت حلب کے حاکم الناصر یوسف نے دمشق لے لیا (648/1250)۔", "c05ddddc"]},
"OLAYLAR_T5_1000B:1253-04-01:0":{"b": ["بیت المقدس صلح کے ذریعے مملوکوں کے حوالے کیا گیا", "50d53fac"], "d": ["خلیفہ کی ثالثی سے ہونے والی صلح کے ذریعے بیت المقدس مملوکوں کے حوالے کر دیا گیا۔", "82982e3a"]},
"OLAYLAR_T5_1000B:1256-01-01:0":{"b": ["بیت المقدس دوبارہ ایوبیوں کے پاس چلا گیا", "fdeedd4a"], "d": ["فلسطین اور بیت المقدس پھر شام کے ایوبیوں کے ہاتھ میں آ گئے۔", "46a6e2a9"]},
"OLAYLAR_T5_1000B:1260-03-01:0":{"b": ["منگولوں نے دمشق لے لیا", "430bdfea"], "d": ["ہلاکو کی شام مہم میں دمشق منگولوں کے ہاتھ آ گیا۔", "407e5d3f"]},
