"OLAYLAR_T5_1000B:1261-06-09:0":{"b": ["بیبرس نے قاہرہ میں عباسی خلافت بحال کی — مکہ اور مدینہ مملوکوں سے وابستہ ہوئے", "a5128a1e"], "d": ["بیبرس نے بغداد کی تباہی سے بچ نکلنے والے عباسی احمد کو قاہرہ میں خلیفہ قرار دے کر بیعت کی؛ خلافت کے سرپرست کی حیثیت سے حرمین کو بھی مملوک بالادستی سے وابستہ کر دیا۔ دن خلافت کی بحالی کا ہے؛ مکہ اور مدینہ کے وابستہ ہونے کا دن ماخذ میں نہیں (حدِ ادنیٰ)۔", "638d550a"]},
"OLAYLAR_T5_1000B:1261-07-25:0":{"b": ["نیقیہ کی فوجیں استنبول میں داخل ہوئیں — بازنطینی سلطنت دوبارہ قائم ہوئی", "81741490"], "d": ["نیقیہ کی فوجوں نے 25 جولائی 1261 کو استنبول میں داخل ہو کر لاطینی حکمرانی ختم کر دی؛ لاسکاری (نیقیہ) ریاست کے علاقے — بورصہ، ازمیر، چمپے، ادرنہ، سالونیکا — پھر بازنطینی سلطنت بن گئے۔ اٹلس ان مقامات پر 1261 سے پہلے کا نیقیہ سلطنت کا دور صرف ان کے لیے دکھاتا ہے جن کا ماخذ میں نام آیا ہے۔", "b389b508"]},
"OLAYLAR_T5_1000B:1271-01-01:0":{"b": ["شارل دانژو نے دوراچ اور کرویا لے لیے", "082a86b8"], "d": ["آنجو خاندان کے شارل نے 1271-1272 میں دوراچ اور کرویا لے کر پرانا قلعہ دوبارہ تعمیر کروایا۔", "e9f84d14"]},
"OLAYLAR_T5_1000B:1284-01-01:0":{"b": ["صقلیوں نے جزیرہ جربہ پر قبضہ کر لیا", "daab5ad2"], "d": ["جزیرہ جربہ 683 (1284-85) میں صقلیوں نے قبضے میں لے لیا؛ پہلے پاپائیت کی ملکیت رہا، پھر سلطنتِ صقلیہ سے وابستہ ہو گیا۔", "691035b3"]},
"OLAYLAR_T5_1000B:1318-01-01:0":{"b": ["یانیا دوبارہ بازنطینی سلطنت میں شامل ہوا", "60016303"], "d": ["تیرھویں صدی کی دوسری نصف میں کئی بار ہاتھ بدلنے والا یانیا 1318 میں دوبارہ بازنطین میں شامل ہوا، تاہم کسی حد تک خودمختاری برقرار رکھی؛ امارتِ ایپیروس کا مرکز آرتا منتقل ہو گیا۔", "14c24d12"]},
